local a = string.find(s, 'local milestone = MILESTONES', 1, true)
return string.sub(s, a-100, a+3800)

local s = game.ServerScriptService.CashInService.Source
local a = string.find(s, 'info = findCollector(pos)', 1, true)
return string.sub(s, a-200, a+2800)

local RS=game:GetService('ReplicatedStorage')
local GA=require(RS.GameAssets)
local keys={}
for k,_ in pairs(GA.Sounds or {}) do table.insert(keys,k) end
local gui=game.Players.LocalPlayer.PlayerGui:FindFirstChild('ShopUi')
local info={}
if gui then for _,c in ipairs(gui.Panel.List:GetChildren()) do if c:IsA('Frame') then local b=c:FindFirstChildWhichIsA('TextButton',true); table.insert(info,{c.Name,b and b.Text,b and b.Active}) end end end
return game:GetService('HttpService'):JSONEncode({sounds=keys,hasPlay=type(GA.play),cards=info})

local out={}
for _,n in ipairs({"Tycoon","CashInService","UpgradeService","DataService","Game"}) do
 local m=game.ServerScriptService:FindFirstChild(n) or game.ServerScriptService:FindFirstChild(n..".server")
 local ok,src=pcall(function() return m.Source end)
 local hits={}
 if ok then for i,l in ipairs(string.split(src,"\n")) do if l:find("RebirthMult") or l:find("cashMult") or l:find("Rebirth") then table.insert(hits,i..":"..l:sub(1,140)) end end end
 out[n]={ok=ok,hits=hits}
end
return game:GetService("HttpService"):JSONEncode(out)

local src=game.ServerScriptService.RebirthService.Source
local lines=string.split(src,"\n")
local out={}
for i=math.max(1,#lines-70),#lines do table.insert(out,i..":"..lines[i]) end
return table.concat(out,"\n")
